css:
@media print {
  @page {
    /* Roll length is selected in the printer driver. */
    size: auto;
    margin: 0;
  }
  html, body {
    width: 80mm;
    margin: 0 !important;
    padding: 0 !important;
    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
  }
}
.print-format {
  width: 72mm;
  max-width: 72mm;
  margin: 0 auto;
  padding: 3mm 2mm;
  color: #000;
  background: #fff;
  font-family: "Courier New", Courier, monospace;
  font-size: 13px;
  line-height: 1.25;
}
.kot { overflow-wrap: anywhere; }
.kot p { margin: 0 0 3px; }
.kot-banner {
  background: #000;
  color: #fff;
  padding: 5px 6px;
  font-size: 15px;
  font-weight: 900;
  text-align: center;
  letter-spacing: 0.5px;
  text-transform: uppercase;
  margin-bottom: 6px;
}
.kot-banner-outline {
  border: 2px solid #000;
  padding: 4px 6px;
  font-size: 12px;
  font-weight: 800;
  text-align: center;
  text-transform: uppercase;
  margin: 6px 0;
}
.kot-station {
  font-size: 18px;
  font-weight: 900;
  text-transform: uppercase;
  border-bottom: 2px solid #000;
  padding-bottom: 3px;
  margin-bottom: 4px;
}
.kot-service {
  font-size: 20px;
  font-weight: 900;
  margin: 4px 0;
}
.kot-meta {
  display: flex;
  justify-content: space-between;
  font-size: 12px;
  margin-bottom: 2px;
}
.kot-items {
  border-top: 2px solid #000;
  border-bottom: 2px solid #000;
  margin: 6px 0;
  padding: 4px 0;
}
.kot-line {
  padding: 6px 0;
  border-bottom: 1px dashed #000;
  break-inside: avoid;
  page-break-inside: avoid;
}
.kot-line:last-child { border-bottom: none; }
.kot-dish {
  display: flex;
  align-items: baseline;
  gap: 6px;
  font-size: 18px;
  font-weight: 900;
}
.kot-qty {
  font-size: 21px;
  min-width: 28px;
}
.kot-mod {
  font-size: 14px;
  font-weight: 700;
  padding-left: 34px;
  margin-top: 2px;
}
.kot-note {
  font-size: 15px;
  font-weight: 900;
  background: #000;
  color: #fff;
  padding: 3px 6px;
  margin: 4px 0 2px 34px;
  white-space: pre-wrap;
}
.kot-order-note {
  font-size: 15px;
  font-weight: 900;
  border: 2px solid #000;
  padding: 5px;
  margin: 6px 0;
  white-space: pre-wrap;
}
.kot-footer {
  font-size: 11px;
  text-align: center;
  margin-top: 6px;
}

.print-format { box-sizing: border-box; }
